import { Box, Stack, Typography } from '@mui/material'
import type { ConfigEntry, ConfigKey } from '../../services/config/config_service'
import type { ConfigSectionProps } from './config_section_props'
import { ConfigSubsection } from './config_subsection'
import { ConfigValueEditor } from './config_value_editor'
import { worktreeService } from '../../services/project/worktree_service'
import { WorktreeConfigList } from './worktree_config_list'

const CONFIG_SECTION_SCROLL_MARGIN_TOP = 3
const PROJECT_CONFIG_SECTION_ID = 'project'
const PROJECT_CONFIG_SECTION_LABEL = 'Project'

interface ProjectConfigGroup {
    description: string
    id: string
    keys: ConfigKey[]
    label: string
}

const PROJECT_CONFIG_GROUPS: ProjectConfigGroup[] = [
    {
        description: 'Where MD² reads and writes this project\'s files. Every folder except the project folder is relative to it.',
        id: 'project-folders',
        keys: [
            'project.projectFolder',
            'project.workingFolder',
            'project.actionsFolder',
            'project.releasesFolder',
            'project.diagramsFolder',
            'project.archivedFolder',
        ],
        label: 'Folders',
    },
    {
        description: 'How cards are named on disk, which card types exist, and which board columns they move through.',
        id: 'project-cards',
        keys: ['project.cardSeparator', 'project.cardTypes', 'project.states'],
        label: 'Cards',
    },
    {
        description: 'How MD² talks to Git for this project.',
        id: 'project-git',
        keys: ['project.diffCommand', 'project.pushMode'],
        label: 'Git',
    },
    {
        description: 'How this project window looks, so parallel projects stay apart.',
        id: 'project-appearance',
        keys: ['project.backgroundShade'],
        label: 'Appearance',
    },
    {
        description: 'Markdown appended to every diagram action prompt.',
        id: 'project-diagrams',
        keys: ['project.diagramFooter'],
        label: 'Diagrams',
    },
]

const GROUPED_PROJECT_CONFIG_KEYS = new Set<ConfigKey>(PROJECT_CONFIG_GROUPS.flatMap((group) => group.keys))

interface ProjectConfigSectionProps extends ConfigSectionProps {
    disabled?: boolean
}

export function ProjectConfigSection(props: ProjectConfigSectionProps) {
    const { disabled = false, draft, entries, onChange, onValidityChange } = props
    const sectionEntries = entries.filter((entry) => entry.section === PROJECT_CONFIG_SECTION_ID)
    const ungroupedEntries = sectionEntries.filter((entry) => entry.editable && !GROUPED_PROJECT_CONFIG_KEYS.has(entry.key))
    const headingId = `${PROJECT_CONFIG_SECTION_ID}-config-heading`

    const renderEntry = (entry: ConfigEntry) => (
        <ConfigValueEditor
            disabled={disabled}
            entry={entry}
            key={entry.key}
            onChange={onChange}
            onValidityChange={onValidityChange}
            value={draft[entry.key]}
            values={draft}
        />
    )

    return (
        <>
            <Box
                aria-labelledby={headingId}
                component="section"
                id={PROJECT_CONFIG_SECTION_ID}
                sx={{ scrollMarginTop: CONFIG_SECTION_SCROLL_MARGIN_TOP }}
            >
                <Stack spacing={4}>
                    <Typography component="h3" id={headingId} variant="h6">
                        {PROJECT_CONFIG_SECTION_LABEL}
                    </Typography>
                    {PROJECT_CONFIG_GROUPS.map((group) => {
                        const groupEntries = group.keys
                            .map((key) => sectionEntries.find((entry) => entry.key === key))
                            .filter((entry): entry is ConfigEntry => !!entry)
                        if (groupEntries.length === 0) return null

                        return (
                            <ConfigSubsection description={group.description} id={group.id} key={group.id} label={group.label}>
                                {groupEntries.map(renderEntry)}
                            </ConfigSubsection>
                        )
                    })}
                    {ungroupedEntries.length > 0 ? (
                        <Stack spacing={3}>
                            {ungroupedEntries.map(renderEntry)}
                        </Stack>
                    ) : null}
                </Stack>
            </Box>
            {worktreeService.isSupported() && !disabled ? <WorktreeConfigList /> : null}
        </>
    )
}

import { Box, CircularProgress, IconButton, Stack, Tooltip, Typography } from '@mui/material'
import Plus from 'mdi-material-ui/Plus'
import { useState } from 'react'
import type { WorktreeRecord, WorktreeRemovalMode } from '../../data/data_types'
import { useWorktreeAdding, useWorktreeDraft } from '../hooks/use_worktrees'
import { dialogService } from '../../services/dialog_service'
import { PrimaryWorktreeSelectionError } from '../../services/project/worktree_errors'
import { worktreeService } from '../../services/project/worktree_service'
import { WorktreeConfigRow } from './worktree_config_row'
import { WorktreeRemoveDialog } from './worktree_remove_dialog'

export function WorktreeConfigList() {
    const draft = useWorktreeDraft()
    const isAdding = useWorktreeAdding()
    const [removeRecord, setRemoveRecord] = useState<WorktreeRecord | null>(null)
    const records = draft?.records ?? []
    const isApplying = draft?.applying ?? false

    const handleAdd = async () => {
        try {
            await worktreeService.selectDraftAddition()
        } catch (error) {
            if (error instanceof PrimaryWorktreeSelectionError) {
                dialogService.displayError(error.message, { title: 'Linked worktree not added' })
                return
            }
            dialogService.error(error, { fallbackMessage: 'Worktree creation failed' })
        }
    }

    const handleRemove = (path: string, pendingAddition: boolean) => {
        try {
            if (pendingAddition) {
                worktreeService.stageDraftRemoval(path)
                return
            }
            const record = records.find((candidate) => candidate.path === path)
            if (!record) throw new Error('Worktree removal target no longer exists')

            setRemoveRecord(record)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Worktree removal could not be opened' })
        }
    }

    const handleRemoveClose = () => {
        setRemoveRecord(null)
    }

    const handleRemoveConfirm = (mode: WorktreeRemovalMode) => {
        try {
            if (!removeRecord) throw new Error('Missing worktree removal target')
            worktreeService.stageDraftRemoval(removeRecord.path, mode)
            setRemoveRecord(null)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Worktree removal failed' })
        }
    }

    return (
        <Stack aria-label="Linked worktrees" spacing={1.25}>
            <Box>
                <Typography component="h3" variant="h6">Linked worktrees</Typography>
                <Typography color="text.secondary" variant="body2">
                    Add chooses an empty folder. Changes are applied to Git only after Save.
                </Typography>
            </Box>
            {records.map((record, index) => (
                <WorktreeConfigRow
                    disabled={isApplying}
                    index={index}
                    key={`${index}-${record.path}`}
                    onRemove={handleRemove}
                    pendingRemoval={draft?.removals.some((removal) => removal.path === record.path)}
                    record={record}
                />
            ))}
            {draft?.additions.map((path, additionIndex) => (
                <WorktreeConfigRow
                    disabled={isApplying}
                    index={records.length + additionIndex}
                    key={path}
                    onRemove={handleRemove}
                    pendingAddition
                    record={{ error: null, path, valid: true }}
                />
            ))}
            <Tooltip title="Add linked worktree">
                <IconButton aria-label="Add linked worktree" disabled={isAdding || isApplying} onClick={handleAdd} size="small" sx={{ alignSelf: 'flex-start' }}>
                    {isAdding ? <CircularProgress aria-label="Selecting linked worktree folder" size={24} /> : <Plus />}
                </IconButton>
            </Tooltip>
            <WorktreeRemoveDialog disabled={isApplying} onClose={handleRemoveClose} onConfirm={handleRemoveConfirm} record={removeRecord} />
        </Stack>
    )
}
